CREATE TABLE IF NOT EXISTS qms.quality_objective(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,objective_name VARCHAR(128) NOT NULL,target_value NUMERIC(12,4) NOT NULL,actual_value NUMERIC(12,4),period_type VARCHAR(16) NOT NULL,responsible_department VARCHAR(64),calculation_rule TEXT,data_source VARCHAR(128),parent_id BIGINT,status VARCHAR(16) NOT NULL DEFAULT '进行中',plant_code VARCHAR(8) NOT NULL,plant_name VARCHAR(32) NOT NULL,created_by VARCHAR(64),updated_by VARCHAR(64),is_deleted SMALLINT NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS qms.internal_audit_plan(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,audit_year INTEGER NOT NULL,audit_scope TEXT,audit_basis VARCHAR(256),auditor_group VARCHAR(256),planned_date DATE,status VARCHAR(16) NOT NULL DEFAULT '草稿',implementation_summary TEXT,plant_code VARCHAR(8) NOT NULL,plant_name VARCHAR(32) NOT NULL,created_by VARCHAR(64),updated_by VARCHAR(64),is_deleted SMALLINT NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS qms.audit_nonconformity(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,audit_plan_id BIGINT NOT NULL,description TEXT NOT NULL,clause_reference VARCHAR(64),severity VARCHAR(16),responsible_department VARCHAR(64),rectification_measure TEXT,due_date DATE,verification_result TEXT,capa_no VARCHAR(64),status VARCHAR(16) NOT NULL DEFAULT '待整改',plant_code VARCHAR(8) NOT NULL,plant_name VARCHAR(32) NOT NULL,created_by VARCHAR(64),updated_by VARCHAR(64),is_deleted SMALLINT NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS qms.adverse_event(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_date TIMESTAMP NOT NULL,product_name VARCHAR(128),product_model VARCHAR(64),product_batch_no VARCHAR(64),event_description TEXT NOT NULL,harm_level VARCHAR(32),patient_info_masked VARCHAR(256),reporter_name VARCHAR(64),report_source VARCHAR(64),assessment_result TEXT,assessor_name VARCHAR(64),report_deadline DATE,report_date DATE,report_receipt_no VARCHAR(64),root_cause TEXT,corrective_action TEXT,responsible_name VARCHAR(64),capa_no VARCHAR(64),status VARCHAR(16) NOT NULL DEFAULT '待评估',plant_code VARCHAR(8) NOT NULL,plant_name VARCHAR(32) NOT NULL,created_by VARCHAR(64),updated_by VARCHAR(64),is_deleted SMALLINT NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS qms.customer_feedback(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,feedback_type VARCHAR(16) NOT NULL,channel VARCHAR(32),customer_name VARCHAR(128),customer_contact VARCHAR(64),product_name VARCHAR(128),product_batch_no VARCHAR(64),content TEXT NOT NULL,feedback_date DATE NOT NULL,category VARCHAR(32),responsible_department VARCHAR(64),investigation TEXT,handling_measure TEXT,customer_reply TEXT,capa_no VARCHAR(64),after_sales_order_id BIGINT,status VARCHAR(16) NOT NULL DEFAULT '待处理',due_date DATE,plant_code VARCHAR(8) NOT NULL,plant_name VARCHAR(32) NOT NULL,created_by VARCHAR(64),updated_by VARCHAR(64),is_deleted SMALLINT NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_audit_nc_due ON qms.audit_nonconformity(plant_code,status,due_date); CREATE INDEX IF NOT EXISTS idx_feedback_due ON qms.customer_feedback(plant_code,status,due_date);
INSERT INTO qms.sys_module(module_code,module_name,status,created_at,updated_at,is_deleted) SELECT 'qualitySystem','体系管理','1',NOW(),NOW(),0 WHERE NOT EXISTS(SELECT 1 FROM qms.sys_module WHERE module_code='qualitySystem' AND is_deleted=0);
INSERT INTO qms.sys_role_permission(role_code,module_code,action_code,created_at,updated_at,is_deleted) SELECT r.role_code,'qualitySystem','VIEW',NOW(),NOW(),0 FROM qms.sys_role r WHERE r.is_deleted=0 AND NOT EXISTS(SELECT 1 FROM qms.sys_role_permission p WHERE p.role_code=r.role_code AND p.module_code='qualitySystem' AND p.action_code='VIEW' AND p.is_deleted=0);
